refrigerate_the_salmon:
def policy():
    salmon = parse_objects("visible salmon")
    if not salmon:
        find("salmon")
        salmon = parse_objects("visible salmon")
    if not salmon or not acquire_object(salmon[0]):
        return False
    find("fridge")
    fridges = parse_objects("visible fridges")
    if not fridges or not place_held_in_container(salmon[0], fridges[0]):
        return False
    return close(fridges[0]).status == "succeeded"

