wash_clothes:
def policy():
    clothes = parse_objects("visible piles of clothes")
    if not clothes:
        find("clothespile")
        clothes = parse_objects("visible piles of clothes")
    if not clothes or not acquire_object(clothes[0]):
        return False
    find("washingmachine")
    machines = parse_objects("visible washing machines")
    if not machines:
        return False
    machine = machines[0]
    if not load_washing_machine(clothes[0], machine):
        return False
    if not run_wash_cycle(machine):
        return False
    if not unload_washing_machine(clothes[0], machine):
        return False
    return parse_question("Am I holding washed clothes?")

put_apple_in_fridge:
def policy():
    find("apple")
    if grab("apple").status != "succeeded":
        return False
    apples = [obj for obj in get_visible_objects() if obj.name == "apple" and is_holding(obj)]
    find("fridge")
    fridges = [obj for obj in get_visible_objects() if obj.name == "fridge"]
    if not apples or not fridges or not place_held_in_container(apples[0], fridges[0]):
        return False
    return close(fridges[0]).status == "succeeded"

